9	import Combine
10	import Foundation
11	import MatrixRustSDK
12	import UIKit
13	
14	class JoinedRoomProxy: JoinedRoomProxyProtocol {
15	    private let roomListService: RoomListServiceProtocol
16	    private let room: RoomProtocol
17	    private let appSettings: AppSettings
18	    private let analyticsService: AnalyticsService
19	    
20	    // periphery:ignore - required for instance retention in the rust codebase
21	    private var roomInfoObservationToken: TaskHandle?
22	    // periphery:ignore - required for instance retention in the rust codebase
23	    private var typingNotificationObservationToken: TaskHandle?
24	    // periphery:ignore - required for instance retention in the rust codebase
25	    private var identityStatusChangesObservationToken: TaskHandle?
26	    // periphery:ignore - required for instance retention in the rust codebase
27	    private var knockRequestsChangesObservationToken: TaskHandle?
28	    
29	    private var innerPinnedEventsTimeline: TimelineProxyProtocol?
30	    private var innerPinnedEventsTimelineTask: Task<Result<TimelineProxyProtocol, RoomProxyError>, Never>?
31	    
32	    private var subscribedForUpdates = false
33	    
34	    /// A room identifier is constant and lazy stops it from being fetched
35	    /// multiple times over FFI
36	    lazy var id: String = room.id()
37	    
38	    var ownUserID: String {
39	        room.ownUserId()
40	    }
41	    
42	    /// The predecessor is set on room creation and never changes, so we lazily store it.
43	    lazy var predecessorRoom = room.predecessorRoom()
44	    
45	    /// The successor may change over time, so we access it dynamically.
46	    /// It's suggested to observe it through the `infoPublisher`
47	    var successorRoom: SuccessorRoom? {
48	        room.successorRoom()
49	    }
50	    
51	    let timeline: TimelineProxyProtocol
52	    
53	    private let infoSubject: CurrentValueSubject<RoomInfoProxyProtocol, Never>
54	    var infoPublisher: CurrentValuePublisher<RoomInfoProxyProtocol, Never> {
55	        infoSubject.asCurrentValuePublisher()
56	    }
57	
58	    private let membersSubject = CurrentValueSubject<[RoomMemberProxyProtocol], Never>([])
59	    var membersPublisher: CurrentValuePublisher<[RoomMemberProxyProtocol], Never> {
60	        membersSubject.asCurrentValuePublisher()
61	    }
62	    
63	    private let typingMembersSubject = CurrentValueSubject<[String], Never>([])
64	    var typingMembersPublisher: CurrentValuePublisher<[String], Never> {
65	        typingMembersSubject.asCurrentValuePublisher()
66	    }
67	    
68	    private let identityStatusChangesSubject = CurrentValueSubject<[IdentityStatusChange], Never>([])
69	    var identityStatusChangesPublisher: CurrentValuePublisher<[IdentityStatusChange], Never> {
70	        identityStatusChangesSubject.asCurrentValuePublisher()
71	    }
72	    
73	    private let knockRequestsStateSubject = CurrentValueSubject<KnockRequestsState, Never>(.loading)
74	    var knockRequestsStatePublisher: CurrentValuePublisher<KnockRequestsState, Never> {
75	        knockRequestsStateSubject.asCurrentValuePublisher()
76	    }
77	    
78	    init(roomListService: RoomListServiceProtocol,
79	         room: RoomProtocol,
80	         appSettings: AppSettings,
81	         analyticsService: AnalyticsService) async throws {
82	        self.roomListService = roomListService
83	        self.room = room
84	        self.appSettings = appSettings
85	        self.analyticsService = analyticsService
86	        
87	        infoSubject = try await .init(RoomInfoProxy(roomInfo: room.roomInfo()))
88	        
89	        let openRoomSpan = analyticsService.signpost.addSpan(.timelineLoad, toTransaction: .openRoom)
90	        timeline = try await TimelineProxy(timeline: room.timelineWithConfiguration(configuration: .init(focus: .live(hideThreadedEvents: appSettings.threadsEnabled),
91	                                                                                                         filter: .eventFilter(filter: Self.excludedEventsFilter(appSettings: appSettings)),
92	                                                                                                         internalIdPrefix: nil,
93	                                                                                                         dateDividerMode: .daily,
94	                                                                                                         trackReadReceipts: .messageLikeEvents,
95	                                                                                                         reportUtds: true)),
96	                                           kind: .live)
97	        openRoomSpan?.finish()
98	        
99	        Task {
100	            await updateMembers()
101	            
102	            // Try to update the encryption state if it's unknown.
103	            // This is an edge case as sliding sync should pass
104	            // that information down to the room info on the rust side.
105	            if room.encryptionState() == .unknown {
106	                MXLog.error("The encryption state should almost always be known.")
107	                _ = try? await room.latestEncryptionState()
108	            }
109	        }
110	    }
111	    
112	    func subscribeForUpdates() async {
113	        guard !subscribedForUpdates else {
114	            MXLog.warning("Room already subscribed for updates")
115	            return
116	        }
117	        
118	        subscribedForUpdates = true
119	
120	        do {
121	            try await roomListService.subscribeToRooms(roomIds: [id])
122	        } catch {
123	            MXLog.error("Failed subscribing to room with error: \(error)")
124	        }
125	        
126	        await timeline.subscribeForUpdates()
127	        
128	        Task {
129	            subscribeToRoomInfoUpdates()
130	            
131	            subscribeToTypingNotifications()
132	            
133	            await subscribeToKnockRequests()
