327	    func updateMembers() async {
328	        // We always update members first using the no sync API in case internet is not readily available
329	        // To get the members stored on disk first, this API call is very fast.
330	        do {
331	            let membersNoSyncIterator = try await room.membersNoSync()
332	            if let members = membersNoSyncIterator.nextChunk(chunkSize: membersNoSyncIterator.len()) {
333	                membersSubject.value = members.map(RoomMemberProxy.init)
334	            }
335	        } catch {
336	            MXLog.error("Failed updating members using no sync API: \(error)")
337	        }
338	        
339	        do {
340	            // Then we update members using the sync API, this is slower but will get us the latest members
341	            let membersIterator = try await room.members()
342	            if let members = membersIterator.nextChunk(chunkSize: membersIterator.len()) {
343	                membersSubject.value = members.map(RoomMemberProxy.init)
344	            }
345	        } catch {
346	            MXLog.error("Failed updating members using sync API: \(error)")
347	        }
348	    }
